# Original Korean teaching text. Technical references are linked per chapter.
DOC='https://docs.xiangshan.cc/projects/design/en/kunminghu-v2/'
REPO='https://github.com/OpenXiangShan/XiangShan'
chapters=[
 dict(slug='start',title='XiangShan을 만나다',tag='시작하기',desc='열린 설계로 들여다보는 고성능 RISC-V 프로세서.',time=6,
 sections=[('설계도를 읽을 수 있는 프로세서','XiangShan(香山)은 공개 소스로 개발되는 고성능 RISC-V 프로세서 프로젝트입니다. 완성된 칩의 사용법을 넘어, 명령어가 어떻게 예측되고 실행되는지 설계 코드까지 따라갈 수 있다는 점이 매력입니다. 이 책은 그 큰 설계를 읽기 위한 첫 지도를 제공합니다.'),('RISC-V와 XiangShan은 어떻게 다른가','RISC-V는 소프트웨어와 하드웨어가 약속하는 명령어 집합 구조(ISA)입니다. XiangShan은 그 약속을 구현하는 프로세서 설계입니다. 같은 악보를 여러 연주자가 연주할 수 있듯, 같은 ISA를 구현해도 내부 파이프라인과 성능은 다를 수 있습니다.'),('세대를 구분하며 읽기','공식 저장소는 Yanqihu, Nanhu, Kunminghu 계열을 구분합니다. 이 책의 설계 설명은 Kunminghu V2 계열 문서를 기준으로 하며, 최신 개발 브랜치와 세부 구현이 같다고 가정하지 않습니다. 실제 연구에서는 브랜치·커밋·Config를 함께 기록하세요.')],
 takeaway='ISA는 외부에 보이는 약속, 마이크로아키텍처는 그 약속을 실행하는 내부 설계입니다.',q='RISC-V와 XiangShan의 관계로 알맞은 것은?',options=['RISC-V는 ISA이고 XiangShan은 이를 구현하는 프로세서다.','둘은 같은 제품의 다른 이름이다.','XiangShan은 운영체제다.'],answer=0,why='ISA를 지키는 여러 구현 중 하나가 XiangShan입니다.',sources=[('XiangShan 공식 저장소',REPO)]),
 dict(slug='pipeline',title='명령어 하나의 여행',tag='큰 그림',desc='가져오기부터 커밋까지, 코어 안의 흐름을 연결합니다.',time=8,
 sections=[('공장처럼 나누어 일하기','한 명령어의 일을 작은 단계로 나누면 여러 명령어가 서로 다른 단계에서 동시에 진행할 수 있습니다. 이 방식이 파이프라이닝입니다. 한 물건의 완성 시간이 그대로여도 공장의 단위 시간당 생산량은 늘어날 수 있습니다.'),('앞에서는 공급하고, 뒤에서는 실행한다','프런트엔드는 다음에 읽을 주소를 예측하고 명령어를 가져옵니다. 백엔드는 명령어를 해석하고 피연산자와 실행 자원이 준비된 작업을 고릅니다. 메모리 명령어는 Load/Store 경로를 통해 데이터를 읽거나 씁니다.'),('실행 완료와 커밋은 다르다','연산 결과가 준비되는 순간과 그 결과를 프로그램의 확정된 상태로 인정하는 순간은 다릅니다. 비순차 실행 코어는 먼저 끝난 결과도 보관했다가, 앞선 명령어에 문제가 없을 때 순서대로 커밋합니다. 아래 구조도는 기능 관계를 요약하며 실제 단계 수나 배선을 나타내지 않습니다.')],
 diagram=True,takeaway='서로 다른 명령어가 겹쳐 진행해도 프로그램이 관찰하는 결과는 올바르게 유지해야 합니다.',q='명령어의 실행이 끝나면 항상 즉시 커밋할 수 있을까요?',options=['네, 완료와 커밋은 같은 뜻이다.','아니요, 앞선 명령어의 상태도 확인해야 한다.'],answer=1,why='정확한 예외와 프로그램 순서를 유지하려면 앞선 명령어를 고려해야 합니다.',sources=[('Kunminghu V2 설계 문서',DOC)]),
 dict(slug='frontend',title='프런트엔드와 명령어 공급',tag='프런트엔드',desc='BPU, FTQ, I-cache가 실행할 일을 미리 준비하는 방법.',time=8,
 sections=[('다음 작업을 미리 준비하는 안내원','분기 명령어의 실제 결과는 실행 후에 알게 됩니다. 그때까지 기다리면 명령어 공급이 자주 끊깁니다. 분기 예측기(BPU)는 다음 주소를 추정해 프런트엔드가 계속 일을 준비하게 합니다.'),('FTQ는 예측과 가져오기를 이어 준다','Fetch Target Queue는 예측된 가져오기 구간에 관한 정보를 보관합니다. 예측하는 쪽과 실제 명령어를 가져오는 쪽을 큐로 연결하면 순간적인 처리 속도 차이를 흡수할 수 있습니다. 큐의 엔트리를 개별 명령어 하나와 동일시하지 않는 것이 중요합니다.'),('명령어 캐시와 버퍼','I-cache는 명령어를 담고 있는 캐시입니다. 가져온 명령어는 후속 처리를 거쳐 백엔드로 전달됩니다. 캐시 미스, 공급 대역폭, 예측 실패는 모두 프런트엔드가 충분한 작업을 공급하지 못하는 원인이 될 수 있습니다. 처리 폭만 늘려서는 모든 병목이 해결되지 않습니다.')],takeaway='예측 정확도와 명령어 공급 능력은 함께 살펴봐야 합니다.',q='FTQ를 두는 이유에 가장 가까운 것은?',options=['모든 메모리 데이터를 영구 저장하려고','분기 명령어를 제거하려고','예측한 가져오기 정보를 보관하고 소비 쪽과 연결하려고'],answer=2,why='FTQ는 프런트엔드의 예측 정보와 fetch 흐름을 연결합니다.',sources=[('BPU와 FTQ 공식 설계',DOC)]),
 dict(slug='prediction',title='분기 예측, 미래를 준비하다',tag='실험 01',desc='2비트 카운터를 조작하고 TAGE-SC의 아이디어로 이어 갑니다.',time=10,
 sections=[('틀릴 수 있지만 기다리지 않는다','반복문의 끝에서 계속 반복할지 빠져나갈지는 제어 흐름을 바꿉니다. 예측이 맞으면 미리 진행한 일이 유효합니다. 틀리면 잘못된 경로의 작업을 버리고 올바른 주소에서 다시 시작해야 합니다.'),('작은 기억에서 긴 이력으로','2비트 포화 카운터는 한 번 반대 결과가 나왔다고 강한 예측을 바로 뒤집지 않습니다. 아래 실험은 이 아이디어만 보여 줍니다. XiangShan의 실제 예측기는 이보다 복잡합니다. TAGE는 길이가 다른 이력을 활용하며 SC는 통계적 정보를 통해 예측을 보정하는 역할을 합니다.'),('해볼 것: 반복문의 마지막 한 번','Taken을 세 번 누른 뒤 Not taken을 한 번 눌러 보세요. 강한 Taken 상태는 한 번의 반대 결과로 약한 Taken이 됩니다. 다음 입력을 누르기 전에 현재 예측을 읽고, 갱신 전 예측이 맞았는지 확인하세요.')],sim='predictor',takeaway='학습은 실제 결과로 상태를 갱신하는 과정입니다. 이 실험은 TAGE-SC 자체의 시뮬레이터가 아닙니다.',q='강한 Taken 상태에서 Not taken이 한 번 관찰되면?',options=['약한 Taken으로 이동한다.','즉시 강한 Not taken으로 이동한다.','상태가 영원히 고정된다.'],answer=0,why='2비트 포화 카운터는 3에서 2로 한 단계 감소합니다.',sources=[('Kunminghu V2 BPU 설계',DOC+'frontend/BPU/')] ),
 dict(slug='rename',title='레지스터 이름 바꾸기',tag='백엔드',desc='같은 이름 때문에 생긴 의존성과 진짜 데이터 의존성을 구분합니다.',time=8,
 sections=[('이름은 같아도 값은 다르다','프로그램은 x1 같은 한정된 레지스터 이름을 반복해서 사용합니다. 서로 다른 명령어가 같은 이름에 새 값을 쓰면 값의 수명을 구분해야 합니다. Rename은 논리 레지스터 이름을 물리 레지스터에 대응시켜 각 버전의 값을 구분합니다.'),('제거할 수 있는 의존성과 없는 의존성','이름을 바꾸면 같은 목적지 이름을 재사용하며 생기는 WAW나 WAR 의존성을 해소할 수 있습니다. 하지만 앞선 명령어가 만든 값을 다음 명령어가 실제로 읽는 RAW 의존성은 사라지지 않습니다. 계산에 필요한 값은 여전히 기다려야 합니다.'),('예측이 틀리면 매핑도 복구한다','잘못된 경로에서 만들어진 레지스터 대응 관계는 올바른 실행에 사용하면 안 됩니다. 프로세서는 리다이렉트 시점에 맞는 상태를 복구해야 합니다. 구현을 읽을 때는 매핑 테이블, 물리 레지스터 할당, 반환, 복구가 서로 일관되는지 함께 보세요.')],takeaway='Rename은 거짓 의존성을 줄이지만 진짜 데이터 의존성을 없애지는 않습니다.',q='Rename만으로 제거할 수 없는 것은?',options=['출력 레지스터 이름의 재사용','앞선 연산 결과를 실제로 읽는 RAW 의존성','서로 다른 값에 같은 이름을 붙인 충돌'],answer=1,why='입력값을 만드는 연산 자체가 끝나야 다음 연산이 그 값을 사용할 수 있습니다.',sources=[('Rename 공식 설계',DOC+'backend/CtrlBlock/Rename/')] ),
 dict(slug='ooo',title='순서를 바꿔 실행하기',tag='실험 02',desc='느린 명령어를 기다리는 동안 다른 일을 끝내는 이유.',time=10,
 sections=[('준비된 작업부터 시작한다','Issue Queue에 있는 명령어는 입력값과 실행 자원이 준비되면 선택될 수 있습니다. 앞선 load가 오래 걸릴 때 그 값에 의존하지 않는 덧셈을 먼저 실행하면 자원을 더 유용하게 쓸 수 있습니다.'),('ROB는 프로그램 순서를 기억한다','Reorder Buffer는 명령어의 순서와 완료 상태를 관리합니다. 뒤의 덧셈이 먼저 완료되어도 앞의 load가 아직 끝나지 않았다면 커밋을 기다립니다. 예외나 분기 예측 실패가 생겼을 때도 프로그램에 보이는 상태를 올바르게 유지해야 합니다.'),('해볼 것: 완료 순서와 커밋 순서 비교','아래 예제는 서로 독립적인 세 명령어가 모두 발행된 상황입니다. 느린 load는 4사이클, 덧셈은 1사이클, 곱셈은 2사이클로 가정합니다. 한 사이클씩 진행하면서 완료는 순서가 바뀌어도 커밋은 앞에서부터 진행됨을 확인하세요.')],sim='rob',takeaway='비순차 실행은 준비된 일을 먼저 하고, 순차 커밋은 프로그램의 의미를 지킵니다.',q='뒤의 명령어가 먼저 완료되어도 커밋이 멈출 수 있는 이유는?',options=['모든 연산의 지연이 같아서','뒤의 명령어 결과가 무조건 틀려서','앞선 명령어가 아직 완료되지 않아서'],answer=2,why='ROB의 선두가 준비되지 않았다면 뒤의 완료된 명령어도 기다립니다.',sources=[('ROB 공식 설계',DOC+'backend/CtrlBlock/Rob/')] ),
 dict(slug='memory',title='Load와 Store의 질서',tag='메모리',desc='메모리 주소가 늦게 밝혀져도 올바른 값을 읽는 방법.',time=8,
 sections=[('같은 주소인지 나중에 알게 된다','레지스터 번호는 명령어를 읽으면 알 수 있지만 메모리 주소는 계산해야 알 수 있습니다. 앞선 store의 주소가 아직 준비되지 않았을 때, 뒤의 load가 같은 주소를 읽는지 즉시 판단하기 어려울 수 있습니다.'),('LSQ와 전달, 재실행','Load/Store Queue는 진행 중인 메모리 작업을 추적합니다. 더 앞선 store가 쓸 데이터를 적절한 조건에서 load로 전달하면 캐시 갱신을 기다리지 않아도 됩니다. 일찍 실행한 load가 순서를 위반한 것이 뒤늦게 확인되면 관련 작업을 재실행해야 합니다.'),('커밋 이후에도 남는 쓰기 작업','프로그램 관점에서 store를 확정하는 것과 캐시·메모리 계층으로 쓰기를 처리하는 것은 구분됩니다. Store Buffer는 이 사이의 작업을 완충합니다. 용량, 병합, 캐시의 처리 능력 때문에 대기와 역압이 생길 수 있습니다.')],takeaway='메모리 명령어의 의존성은 실제 주소와 실행 상태를 함께 확인해야 합니다.',q='앞선 store와 뒤의 load의 의존성을 판단할 때 중요한 것은?',options=['두 명령어가 접근하는 주소와 데이터 준비 상태','명령어의 글자 수','소스 파일 이름'],answer=0,why='같은 메모리 위치를 다루는지와 전달할 값이 준비되었는지가 핵심입니다.',sources=[('LSQ 공식 설계',DOC+'memblock/LSU/LSQ/')] ),
 dict(slug='cache',title='캐시와 주소 변환',tag='실험 03',desc='작은 캐시로 지역성을 관찰하고 TLB와의 차이를 익힙니다.',time=10,
 sections=[('자주 쓰는 데이터를 가까이 둔다','캐시는 데이터의 일부를 가까운 저장 공간에 유지합니다. 최근 읽은 위치를 다시 읽는 시간 지역성과, 그 주변을 읽는 공간 지역성을 활용합니다. 적중하면 먼 메모리까지 갈 필요가 줄지만 모든 접근이 적중하는 것은 아닙니다.'),('같은 위치를 놓고 경쟁할 때','아래는 4개의 라인과 라인당 16바이트를 가진 직접 사상 캐시 모형입니다. 블록 번호를 4로 나눈 나머지가 인덱스가 됩니다. 주소 0과 64를 번갈아 읽으면 같은 라인을 교체하며 충돌 미스가 발생합니다. 실제 XiangShan의 크기·연관도·지연을 재현하지는 않습니다.'),('TLB는 데이터 캐시가 아니다','프로그램의 가상 주소를 물리 주소로 바꾸려면 주소 변환이 필요합니다. TLB는 이 변환 정보를 캐시합니다. TLB 미스는 데이터 캐시 미스와 다른 사건입니다. 둘 중 하나만 보아서는 메모리 접근이 느려진 이유를 충분히 설명할 수 없습니다.')],sim='cache',takeaway='캐시는 데이터를, TLB는 주소 변환 정보를 재사용합니다.',q='이 실험에서 주소 0을 읽은 직후 주소 4를 읽으면?',options=['항상 충돌 미스다.','같은 16바이트 블록이므로 적중한다.','TLB의 크기가 바뀐다.'],answer=1,why='주소 0부터 15까지는 같은 블록에 속합니다.',sources=[('Data Cache 및 MMU 공식 설계',DOC)] ),
 dict(slug='verification',title='설계에서 검증까지',tag='개발 흐름',desc='Chisel, RTL, 시뮬레이션, DiffTest의 역할을 구분합니다.',time=8,
 sections=[('Chisel로 하드웨어를 표현한다','XiangShan의 주요 설계는 Scala 기반 하드웨어 구성 언어인 Chisel로 작성됩니다. 소스와 구성을 elaboration하여 RTL을 생성합니다. 소프트웨어처럼 반복문이 있다고 해서 칩이 그 반복문을 순서대로 실행한다고 해석하면 안 됩니다. 생성되는 하드웨어 구조를 살펴봐야 합니다.'),('참조 모델과 실행을 비교한다','DiffTest는 DUT와 참조 모델의 실행 결과를 비교해 기능 오류를 찾는 데 사용됩니다. 시뮬레이션에서 실행한 프로그램에 대해 차이를 포착할 수 있지만, 실행하지 않은 모든 경우까지 증명한 것은 아닙니다.'),('무엇을 검증했는지 기록한다','성능을 비교하려면 같은 워크로드, 설정, 계측 구간을 사용해야 합니다. RTL 변경 전후의 등가성을 확인하는 formal equivalence와 프로그램을 돌려 보는 DiffTest는 서로 다른 근거를 제공합니다. 재현을 위해 소스 커밋, Config, 도구 버전, 실행 명령을 함께 남기세요.')],takeaway='기능 검증, 성능 평가, RTL 등가성 검증은 질문과 근거가 서로 다릅니다.',q='DiffTest를 통과했다는 사실만으로 말할 수 없는 것은?',options=['실행한 테스트에서 비교 결과가 일치했다.','모든 입력과 모든 상태에서 두 RTL이 등가임이 증명되었다.'],answer=1,why='테스트 통과와 모든 경우에 대한 형식적 증명은 구분해야 합니다.',sources=[('XiangShan 공식 저장소',REPO),('DiffTest 공식 저장소','https://github.com/OpenXiangShan/difftest')] ),
 dict(slug='reading',title='소스 읽기를 시작하는 지도',tag='다음 단계',desc='문서와 소스를 함께 읽고, 나만의 질문을 만들어 보세요.',time=6,
 sections=[('버전부터 고정하기','문서를 읽기 전에 저장소의 브랜치를 확인하고 git rev-parse HEAD로 커밋을 기록하세요. 이 책은 Kunminghu V2 문서의 개념을 바탕으로 합니다. 다른 세대의 설명을 현재 체크아웃에 그대로 적용하지 말고 공식 문서의 버전 선택기를 확인하세요.'),('작은 질문으로 시작하기','처음부터 모든 파일을 읽기보다 “분기 예측 실패는 어디로 전달될까?”처럼 좁은 질문을 정하세요. 관련 모듈의 입출력, 상태 레지스터, valid/ready 조건을 따라가고 이해한 동작을 작은 예제로 확인합니다. 용량이나 폭은 이름만으로 추정하지 말고 Config와 파라미터를 확인하세요.'),('다음 실험을 설계하기','예측 정확도, 캐시 미스, 실행 자원 대기 중 하나를 골라 원인을 설명하는 가설을 세워 보세요. 바꾸는 조건은 하나씩 제한하고 변경 전후의 기능을 먼저 확인하세요. 브라우저의 교육용 실험에서 나온 수치를 실제 코어의 성능 결과로 사용해서는 안 됩니다.')],takeaway='버전 → 질문 → 신호 → 작은 검증의 순서로 읽으면 복잡한 설계도 추적할 수 있습니다.',q='실험 결과를 재현하려면 무엇을 함께 남겨야 할까요?',options=['최종 숫자 하나만','화면 색상만','커밋, Config, 도구와 실행 조건'],answer=2,why='소스와 구성 및 실험 조건이 달라지면 결과도 달라질 수 있습니다.',sources=[('공식 소스 코드',REPO+'/tree/kunminghu-v2/src/main/scala'),('공식 사용자 가이드','https://docs.xiangshan.cc/projects/user-guide/en/kunminghu-v2/')] )
]
